const attachDrag = () => {
  let active = false
  const onMove = (e: PointerEvent) => {
    if (!active) return
    // Map pointer screen X directly relative to screen center
    const currentScale = s()
    const physicalOffsetFromCenter = e.clientX - window.innerWidth / 2
    let lx = 540 + (physicalOffsetFromCenter / currentScale)
    basketX = Math.max(basketLogicalW / 2, Math.min(1080 - basketLogicalW / 2, lx))
  }
  const end = () => {
    active = false
    window.removeEventListener('pointermove', onMove)
    window.removeEventListener('pointerup', end)
    window.removeEventListener('pointercancel', end)
  }
  const startDrag = (e: Event) => {
    const pe = e as PointerEvent
    active = true
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', end)
    window.addEventListener('pointercancel', end)
    onMove(pe)
  }

  // Attach to pa-root so dragging works from anywhere on the screen,
  // including the footer bar.
  const paRoot = root.closest('.pa-root') || document.body
  paRoot.addEventListener('pointerdown', startDrag)
}

