const tick = (t: number) => {
  if (done) return
  const dt = Math.min(64, t - lastTime) / 1000
  lastTime = t

  const hdrBar = document.querySelector('[data-id="basket_bar"]') as HTMLElement | null
  const gameRect = root.getBoundingClientRect()
  const currentScale = s()

  if (!hdrBar || !gameRect) {
    rafRef = requestAnimationFrame(tick)
    return
  }

  const footerRect = hdrBar.getBoundingClientRect()
  const gameCenterX = gameRect.left + gameRect.width / 2
  const basketScreenY = footerRect.top

  let anyCaught = false

  for (let i = drops.length - 1; i >= 0; i--) {
    const d = drops[i]
    if (d.captured) continue

    const prevScreenY = gameRect.top + d.y * currentScale
    d.y += d.speed * dt
    const newScreenY = gameRect.top + d.y * currentScale

    // Hit detection: item crossed the basket line this frame
    if (prevScreenY < basketScreenY && newScreenY >= basketScreenY) {
      const item_screen_x = gameCenterX + (d.x - 540) * currentScale
      const basket_screen_x = gameCenterX + (basketX - 540) * currentScale

      const hit = Math.abs(item_screen_x - basket_screen_x) < (basketLogicalW / 2 + itemSz * 0.3) * currentScale
      if (hit) {
        anyCaught = true
        d.captured = true

        // Hide caught items
        if (d.el && d.el.parentNode) {
          d.el.parentNode.removeChild(d.el)
        }
        continue
      }
    }

    if (d.el && !d.captured) {
      d.el.style.top = `${d.y - itemSz / 2}px`
    }

    // Cleanup offscreen
    if (newScreenY > basketScreenY + 500 * currentScale) {
      if (d.el && d.el.parentNode) d.el.parentNode.removeChild(d.el)
      drops.splice(i, 1)
    }
  }

  if (anyCaught) {
    caught++
    ctx.sfx.play('catch')
    updateScoreUI()
    if (caught >= need) {
      done = true
      ctx.sfx.play('win')
      completeCb?.()
    }
  }
  if (basket) {
    basket.style.width = (basketLogicalW * currentScale) + 'px'
    basket.style.height = (150 * currentScale) + 'px'
    basket.style.marginLeft = `-${(basketLogicalW / 2) * currentScale}px`
    basket.style.transform = `translateX(${(basketX - 540) * currentScale}px)`
  }

  rafRef = requestAnimationFrame(tick)
}

